import{z as l,x as i,o as e,c as s,q as B,j as r,D as E,d as A,s as o,S as t}from"./chunks/framework.C8m1ZpeB.js";const c=JSON.parse('{"title":"基金流与回报追逐","description":"","frontmatter":{"title":"基金流与回报追逐","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/fund-flows-chasing.md","filePath":"quant/fund-flows-chasing.md","lastUpdated":1791063341000}'),d={name:"quant/fund-flows-chasing.md"};function p(h,a,u,f,C,_){const n=i("Mermaid");return e(),s("div",null,[a[2]||(a[2]=B('<h1 id="基金流与回报追逐" tabindex="-1">基金流与回报追逐 <a class="header-anchor" href="#基金流与回报追逐" aria-label="Permalink to &quot;基金流与回报追逐&quot;">​</a></h1><div class="epigraph"><p>资金对过去业绩的反应是凸的：大赢家大进、中庸几乎不动、输家流出有限；于是行业的增量资金总是在追已经变贵的策略。</p><footer>—— Sirri and Tufano, Costly Search and Mutual Fund Flows, Journal of Finance, 1998；均衡摊薄见 Berk and Green</footer></div><p><a href="/quant/performance-persistence">上一课</a>把弱持续性留给资金流来完成故事。本课的缺口是<strong>流本身</strong>：申购赎回如何依赖过去收益，以及流如何反作用于价格与随后收益。Sirri–Tufano 记录凸性的业绩–流关系；Chevalier–Ellison 把它接到锦标赛激励。Coval–Stafford 写流出引发的被迫交易与火灾抛售。Lou 把流导致的持仓联动写成可预测的价格压力。本课接策略地图里的被动流与主题 ETF：零售与机构的主动流是同一管道的另一条。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>凸性意味着：去年的明星基金吸收不成比例的 AUM，容量约束立刻收紧，预期净 alpha 下降——这正是 Berk–Green 的机制。问题是可交易性：能否做「买流入、卖流出」？短期价格压力可能为正（流入推高持仓股），随后反转。这与 <a href="/quant/index-inclusion-passive-flow">指数纳入</a> 同类，但流是内生的业绩函数，前视偏差更大。回测必须用滞后已公布的 AUM 与持仓，不能用期末同时流。</p><p><span class="marginnote">直觉类比：业绩–流的凸性像网红店排队——门口人越多，新顾客越觉得「值得排」，赢家通吃；但厨房里的厨师（基金经理的技能）没变，客人翻倍，每桌菜（alpha）必然变淡。这就是 Berk–Green 摊薄的直觉。</span></p><p>锦标赛：年中落后的经理加大风险，见激励费课的水位逻辑。流的凸性加 HWM，使行业在牛市同步加杠杆。</p><h3 id="流不是-alpha-信号本身" tabindex="-1">流不是 alpha 信号本身 <a class="header-anchor" href="#流不是-alpha-信号本身" aria-label="Permalink to &quot;流不是 alpha 信号本身&quot;">​</a></h3><p>把「聪明钱」流当因子，常常只是动量加规模。正交后再看残差。机构单独账户与共同基金的流信息含量不同，不可混成一个「资金流因子」去对抗价值。</p><p><span class="marginnote">术语翻译：「正交后再看残差」就是先把流里能被动量和规模解释的部分扣掉，只拿剩下的部分检验有没有预测力——防止把动量换了个名字，当成新因子卖。</span></p>',10)),(e(),r(t,null,{default:E(()=>[o(n,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20T0%5B%22%E5%AD%A3%E5%BA%A6%E6%9C%AB%EF%BC%9A%E5%9F%BA%E9%87%91%E5%AE%9E%E7%8E%B0%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20T1%5B%22%E9%9A%8F%E5%90%8E%E4%B8%80%E5%AD%A3%EF%BC%9A%E7%94%B3%E8%B5%8E%E5%86%B3%E7%AD%96%E4%B8%8E%E8%B5%84%E9%87%91%E5%88%B0%E8%B4%A6%22%5D%0A%20%20T1%20--%3E%20T2%5B%22%E5%AD%A3%E5%BA%A6%E6%9C%AB%EF%BC%9AAUM%20%E4%B8%8E%E6%8C%81%E4%BB%93%E5%85%AC%E5%B8%83%22%5D%0A%20%20T2%20--%3E%20T3%5B%22%E5%86%8D%E4%B8%8B%E4%B8%80%E6%9C%9F%EF%BC%9A%E7%A0%94%E7%A9%B6%E8%80%85%E6%89%8D%E7%9C%8B%E5%BE%97%E5%88%B0%22%5D%0A%20%20T3%20--%3E%20OK%5B%22%E5%8F%AA%E7%94%A8%E5%B7%B2%E5%85%AC%E5%B8%83%E7%9A%84%E6%BB%9E%E5%90%8E%E6%95%B0%E6%8D%AE%EF%BC%9A%E5%90%88%E6%B3%95%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20T3%20--%3E%20BAD%5B%22%E5%81%B7%E7%9C%8B%E6%9C%9F%E6%9C%AB%E5%90%8C%E6%97%B6%E6%B5%81%EF%BC%9A%E5%89%8D%E8%A7%86%22%5D%0A%20%20OK%20--%3E%20TRADE%5B%22%E5%8F%AF%E4%BA%A4%E6%98%93%E7%89%88%E6%9C%AC%EF%BC%9A%E6%BB%9E%E5%90%8E%E5%BB%BA%E4%BB%93%20%2B%20%E5%AE%B9%E9%87%8F%E5%8F%97%E9%99%90%22%5D%0A%20%20BAD%20--%3E%20FANTASY%5B%22%E7%BA%B8%E9%9D%A2%E5%A4%8F%E6%99%AE%E8%99%9A%E9%AB%98%EF%BC%8C%E5%AE%9E%E7%9B%98%E6%97%A0%E6%B3%95%E5%A4%8D%E5%88%B6%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=B('<p><span class="marginnote">为什么重要：回测若用了期末同时流的 AUM，等于假装在数据公布前就知道钱进了哪些股票——这些股票本季的上涨会被凭空记进「信号」。这一步错，整个资金流策略的回测收益都是海市蜃楼。</span></p><p><span class="marginnote">火灾抛售提供流动性补偿，不是免费。承接赎回的人吃冲击、借券与污名风险，夏普要用事件窗口的缺口情景，不能用平静期。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>度量：滞后收益 → 流的回归（分段、凸性）。价格：流入基金重仓股的随后收益，控制动量。策略：只在可观测滞后上交易，容量按基金持仓可交易性。风险：同风格基金相关流（主题课）。与回购流、指数流分列归因。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>搜寻成本与广告使投资人追明星（Sirri–Tufano）。技能有限时，AUM 上升摊薄（Berk–Green）。被迫交易把流写成价格（Coval–Stafford）。于是业绩持续性在可投资端消失：你看到的热手，已经在吸收会毁掉热手的钱。</p>',6)),(e(),r(t,null,{default:E(()=>[o(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20Ret%5B%22%E8%BF%87%E5%8E%BB%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Convex%5B%22%E5%87%B8%E6%80%A7%E6%B5%81%E5%85%A5%22%5D%0A%20%20Convex%20--%3E%20AUM%5B%22%E8%A7%84%E6%A8%A1%E7%A2%B0%E5%88%B0%E5%AE%B9%E9%87%8F%22%5D%0A%20%20AUM%20--%3E%20Thin%5B%22%E5%87%80%20alpha%20%E6%91%8A%E8%96%84%22%5D%0A%20%20Convex%20--%3E%20Press%5B%22%E6%8C%81%E4%BB%93%E8%82%A1%E4%BB%B7%E6%A0%BC%E5%8E%8B%E5%8A%9B%22%5D%0A%20%20Press%20--%3E%20Rev%5B%22%E9%9A%8F%E5%90%8E%E5%8F%8D%E8%BD%AC%E6%88%96%E7%81%AB%E7%81%BE%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写如何利用未公开申赎清单。ETF 一级申赎与共同基金零售流机制不同，见被动流课。对冲基金的锁定期推迟流，改变凸性形状。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>业绩–流关系是凸的，增量资金追明星、摊薄技能。</li><li>流造成的价格压力可测，但须用滞后数据。</li><li>火灾抛售是流动性补偿，不是平静期 alpha。</li><li>出处：Sirri and Tufano, <em>JF</em>, 1998；Berk and Green, <em>JPE</em>, 2004；Coval and Stafford；Lou 对持仓流。</li></ul>',4))])}const m=l(d,[["render",p]]);export{c as __pageData,m as default};
